  const record=progress().miniRecord??={draft:null,last:null};
  renderTask(current.mini,$('#microtask'),(value,correct,button)=>{record.last=correct;record.draftDirty=false;touch();log('foundation_answer',{lesson:current.id,value,correct});$('#micro-feedback').textContent=b(current.mini.feedback[value]);button.classList.add(correct?'correct':'wrong');},{prefix:'mini',record});
  if(record.draft!==null)$('#micro-feedback').textContent=b(current.mini.feedback[record.draft]);
  $('#back-to-step').onclick=()=>{$('#mini-box').innerHTML='';$('#question button,#question input,#question select')?.focus();};
