function attemptFingerprint(attempt) {
  // Archive bookkeeping does not make a learner's unchanged answers a new attempt.
  const clean=Object.fromEntries(Object.entries(attempt).filter(([key])=>!['archiveReason','archivedAt','importSnapshotOf'].includes(key)));
  const canonical=value=>Array.isArray(value)?value.map(canonical):value&&typeof value==='object'?Object.fromEntries(Object.keys(value).sort().map(key=>[key,canonical(value[key])])):value;
  const text=JSON.stringify(canonical(clean));let a=2166136261,b=5381;
  for(let i=0;i<text.length;i++){a=Math.imul(a^text.charCodeAt(i),16777619);b=Math.imul(b,33)^text.charCodeAt(i);}
  return (a>>>0).toString(16).padStart(8,'0')+(b>>>0).toString(16).padStart(8,'0');
}
function validateAttempt(raw,id) {
  const fail=()=>{throw Error(t('Tệp có cấu trúc lượt làm không hợp lệ: ','Invalid attempt structure: ')+id);};
  if(!raw||typeof raw!=='object'||Array.isArray(raw)||!raw.steps||typeof raw.steps!=='object'||Array.isArray(raw.steps))fail();
  const isText=x=>typeof x==='string'&&x.length<=16000;
  if(raw.attemptId!==undefined&&(!isText(raw.attemptId)||!raw.attemptId.length||raw.attemptId.length>160))fail();
  if(raw.number!==undefined&&(!Number.isInteger(raw.number)||raw.number<1||raw.number>100000))fail();
  if(raw.lastStage!==undefined&&(!Number.isInteger(raw.lastStage)||raw.lastStage<0||raw.lastStage>5))fail();
  const l=BANK.find(x=>x.id===id);
  const validateRecord=(s,task,variant=false)=>{
    if(!s||typeof s!=='object'||Array.isArray(s)||!Number.isInteger(s.tries)||s.tries<0||s.tries>1000000)fail();
    for(const key of ['first','last','firstSupported'])if(s[key]!==undefined&&s[key]!==null&&typeof s[key]!=='boolean')fail();
    for(const key of ['done','supported','paper','hintOpen','referenceSeen','draftDirty','legacySupportUnknown'])if(s[key]!==undefined&&typeof s[key]!=='boolean')fail();
    if(!variant&&typeof s.done!=='boolean')fail();
    const validateValue=(value,draft=false)=>{
      if(value===null||value===undefined)return;
      if(task.type==='choice'){if(!Number.isInteger(value)||value<0||value>=task.options.length)fail();}
      else if(!Array.isArray(value)||value.length!==(task.fields||task.rows).length||value.some((v,i)=>draft?(typeof v!=='string'&&typeof v!=='number')||String(v).length>80:!Number.isFinite(v)||(task.type==='match'&&(!Number.isInteger(v)||v<0||v>=task.rows[i].options.length))))fail();
    };
    validateValue(s.draft,true);validateValue(s.lastValue);
    if(s.sources!==undefined&&(!Array.isArray(s.sources)||s.sources.some(x=>!isText(x))))fail();
    if(s.model!==undefined&&s.model!==null&&(!isText(s.model)||s.model.length>1200))fail();
    if(s.answers!==undefined){if(!Array.isArray(s.answers)||s.answers.length>100000)fail();for(const a of s.answers){if(!a||typeof a.correct!=='boolean'||typeof a.supported!=='boolean')fail();validateValue(a.value);}}
  };
  for(const [k,s] of Object.entries(raw.steps)){if(!/^[0-5]$/.test(k))fail();validateRecord(s,l.steps[+k]);}
  if(raw.variant!==null&&raw.variant!==undefined)validateRecord(raw.variant,l.variant.task,true);
  if(raw.reading!==undefined){if(!raw.reading||typeof raw.reading!=='object'||Array.isArray(raw.reading))fail();for(const [key,note] of Object.entries(raw.reading)){if(!['main','variant'].includes(key)||!note||typeof note!=='object')fail();for(const n of ['facts','goal','relation','check'])if(note[n]!==undefined&&(!isText(note[n])||note[n].length>1500))fail();}}
  if(raw.ai!==undefined){
    if(!raw.ai||typeof raw.ai!=='object'||Array.isArray(raw.ai))fail();
    for(const [key,record] of Object.entries(raw.ai)){
      if(!/^[A-Za-z0-9_-]+:(vi|en)$/.test(key)||!record||typeof record!=='object'||Array.isArray(record))fail();
      for(const k of ['response','displayResponse','prompt','question'])if(record[k]!==undefined&&!isText(record[k]))fail();
      if(record.goal!==undefined&&!['reading','relation','next','check'].includes(record.goal))fail();
      for(const k of ['includeDraft','needsRefresh','reviewed','used'])if(record[k]!==undefined&&typeof record[k]!=='boolean')fail();
      const checkList=value=>{if(value!==undefined&&(!Array.isArray(value)||value.some(x=>typeof x!=='boolean')))fail();};
      checkList(record.checks);
      const request=value=>{if(value!==undefined&&value!==null&&(!value||typeof value!=='object'||Array.isArray(value)||value.schema!=='caunoi.ai.request.v2'||['request_id','lesson_id','attempt_id','step_id','language'].some(k=>!isText(value[k])||!value[k].length||value[k].length>160)))fail();};
      request(record.request);
      if(record.previous!==undefined){if(!Array.isArray(record.previous)||record.previous.length>100000)fail();for(const prior of record.previous){if(!prior||typeof prior!=='object'||Array.isArray(prior))fail();request(prior.request);checkList(prior.checks);for(const k of ['prompt','response'])if(prior[k]!==undefined&&!isText(prior[k]))fail();}}
    }
  }
  if(raw.simulation!==undefined){
    const s=raw.simulation,config=l.simulation;
    if(!s||typeof s!=='object'||Array.isArray(s))fail();
    if(s.x!==undefined&&(!Number.isFinite(s.x)||s.x<config.min||s.x>config.max||Math.abs((s.x-config.min)/config.step-Math.round((s.x-config.min)/config.step))>1e-7))fail();
    if(s.p!==undefined&&(!Number.isFinite(s.p)||s.p<0||s.p>1))fail();
    if(config.type==='work_balance'){for(const k of ['a','b'])if(s[k]!==undefined&&(!Number.isInteger(s[k])||s[k]<5||s[k]>120))fail();if(s.q!==undefined&&![.25,.5,1,1.5,2].includes(s.q))fail();if(s.mode!==undefined&&!['both','a','b'].includes(s.mode))fail();if(s.time!==undefined&&(!Number.isFinite(s.time)||s.time<0||s.time>240))fail();if(s.hints!==undefined&&(!Array.isArray(s.hints)||s.hints.some(h=>!['H1','H2','H3','H4'].includes(h))))fail();if(s.observations!==undefined){if(!Array.isArray(s.observations)||s.observations.length>6)fail();for(const o of s.observations){if(!o||!Number.isInteger(o.a)||o.a<5||o.a>120||!Number.isInteger(o.b)||o.b<5||o.b>120||![.25,.5,1,1.5,2].includes(o.q)||!['both','a','b'].includes(o.mode)||!Number.isFinite(o.time)||o.time<0||o.time>240)fail();}}}
  }
  const p=normalizeAttempt(structuredClone(raw));
  if(!raw.attemptId)p.attemptId='legacy-'+id+'-'+attemptFingerprint(raw);
  return p;
}
function importProgressObject(x) {
  if(!x||x.schema!=='caunoi.progress.v5'||!['5.0','5.1'].includes(x.version)||!x.progress||typeof x.progress!=='object'||Array.isArray(x.progress))throw Error(t('Tệp không phải bản xuất tiến độ v5.0 hoặc v5.1.','Expected a v5.0 or v5.1 progress export.'));
  const known=id=>BANK.some(l=>l.id===id),clean={},history={};
  for(const [id,p] of Object.entries(x.progress)){if(!known(id))throw Error(t('Mã bài không hợp lệ: ','Invalid lesson: ')+id);clean[id]=validateAttempt(p,id);}
  if(x.history!==undefined&&(!x.history||typeof x.history!=='object'||Array.isArray(x.history)))throw Error(t('Lịch sử không hợp lệ.','Invalid history.'));
  for(const [id,items] of Object.entries(x.history||{})){if(!known(id)||!Array.isArray(items)||items.length>10000)throw Error(t('Lịch sử lượt làm không hợp lệ.','Invalid attempt history.'));history[id]=items.map(p=>validateAttempt(p,id));}
  // Validate everything before changing live state; imported research fields are ignored.
  let added=0,archived=0;
  const fingerprint=attemptFingerprint;
  const mergeHistory=(id,p)=>{
    const existing=[state.progress[id],...(state.history[id]||[])].filter(Boolean);
    if(existing.some(q=>q.attemptId===p.attemptId&&fingerprint(q)===fingerprint(p)))return;
    if(existing.some(q=>q.attemptId===p.attemptId))p={...p,attemptId:p.attemptId+'-import-'+fingerprint(p),importSnapshotOf:p.attemptId};
    const list=state.history[id]??=[];if(list.some(q=>q.attemptId===p.attemptId))return;
    list.push({...p,archiveReason:'import'});archived++;
  };
  for(const [id,p] of Object.entries(clean)){if(!state.progress[id]){state.progress[id]=p;added++;}else mergeHistory(id,p);}
  for(const [id,items] of Object.entries(history))for(const p of items)mergeHistory(id,p);
  if(!state.lastLesson&&known(x.lastLesson))state.lastLesson=x.lastLesson;
  save();return {added,archived};
}
