function packageEvents() {
  if(!state.events.length||!state.study)return;
  const base={schema:'caunoi.batch.v3',student_code:state.study.code,grade:state.study.grade,phase:state.study.phase};
  let events=[],version=null;
  const flush=()=>{if(events.length)state.outbox.push({...base,content_version:version,batch_id:uid(),events});events=[];};
  for(const event of state.events) {
    const eventVersion=event.data?.content_version||'learning5.0';
    if(version!==eventVersion){flush();version=eventVersion;}
    const trial={...base,content_version:version,batch_id:uid(),events:[...events,event]};
    if(events.length>=40||new TextEncoder().encode(JSON.stringify(trial)).length>28000)flush();events.push(event);
  }
  flush();state.events=[];save();
}
async function readAloud() {
  const token=readAloud.token=(readAloud.token||0)+1;
  window.speechSynthesis?.cancel();tts?.pause();
  const isVariant=progress().lastView==='variant',story=b(isVariant?current.variant.story:current.story),status=$('#audio-status');
  if(!isVariant&&SITE.audioBase){tts=new Audio(`${SITE.audioBase.replace(/\/$/,'')}/${L()}/${current.id}.mp3`);try{await tts.play();status.textContent=t('Đang phát bản đọc đề của bài.','Playing the lesson recording.');return;}catch(e){}}
  if(!('speechSynthesis' in window)){status.textContent=t('Thiết bị chưa hỗ trợ giọng đọc. Em có thể đọc toàn bộ đề ở phía trên.','Speech is unavailable. The full problem text appears above.');return;}
  const voices=()=>speechSynthesis.getVoices().filter(v=>v.lang.toLowerCase().startsWith(L()));
  if(!voices().length)await new Promise(resolve=>{const finish=()=>{speechSynthesis.removeEventListener('voiceschanged',finish);resolve();};speechSynthesis.addEventListener('voiceschanged',finish,{once:true});setTimeout(finish,800);});
  if(token!==readAloud.token||!status.isConnected)return;
  const voice=voices()[0];
  if(!voice){status.textContent=t('Chưa có giọng tiếng Việt trên thiết bị. Em đọc đề bằng chữ hoặc nhờ thầy cô bổ sung giọng đọc.','No English voice is available. Read the text or ask your teacher to add a voice.');return;}
  const utterance=new SpeechSynthesisUtterance(story);utterance.voice=voice;utterance.lang=L()==='vi'?'vi-VN':'en-US';utterance.rate=.9;speechSynthesis.speak(utterance);status.textContent=t('Đang đọc đề bằng giọng của thiết bị.','Reading the problem with the device voice.');
}

