function renderDemo(){
 const external=demoMode==='outside',seen=demoExplained;
 $('#demo-host').innerHTML=`<div class="demo-card"><div class="demo-head"><span class="eyebrow">${t('Từ câu chữ đến quan hệ','From words to relationships')}</span><div class="demo-tabs" aria-label="${t('Đổi tình huống','Change situation')}"><button data-demo-mode="transfer" aria-pressed="${!external}">${t('Chuyển A → B','Move A → B')}</button><button data-demo-mode="outside" aria-pressed="${external}">${t('Để ra ngoài','Take outside')}</button></div></div><div class="demo-inner"><p class="demo-story">${external?t('Lấy 8 quyển sách từ tủ A để riêng. Khi đó, hai tủ A và B có số sách bằng nhau.','Take 8 books out of cupboard A and set them aside. The two cupboards then hold equal numbers of books.'):t('Chuyển 8 quyển sách từ tủ A sang tủ B thì số sách trong hai tủ bằng nhau.','Move 8 books from cupboard A to cupboard B. The two cupboards then hold equal numbers of books.')}</p><p class="demo-definition">${t('Gọi x, y là số sách của A, B lúc đầu.','Let x and y be the initial book counts in A and B.')}</p><div class="demo-stage" aria-label="${seen?t('A còn x trừ 8; B có ','A has x minus 8; B has ')+(external?'y':t('y cộng tám','y plus eight')):t('Ban đầu tủ A có x quyển, tủ B có y quyển.','Initially A has x books and B has y books.')}"><div class="cupboard"><span class="cupboard-title">${t('Tủ sách A','Cupboard A')}</span><span class="symbol">${seen?'x − 8':'x'}</span><small>${seen?t('Sau thao tác','After the action'):t('Lúc đầu','Initially')}</small></div><div class="demo-arrow">${icon(external?'download':'arrow')}<span>${external?t('8 quyển ra ngoài','8 books outside'):t('Chuyển 8 quyển','Move 8 books')}</span></div><div class="cupboard b"><span class="cupboard-title">${t('Tủ sách B','Cupboard B')}</span><span class="symbol">${seen&&!external?'y + 8':'y'}</span><small>${seen?t('Sau thao tác','After the action'):t('Lúc đầu','Initially')}</small></div></div><p class="demo-question">${t('Em dự đoán số sách ở B thay đổi thế nào?','How do you expect the number of books in B to change?')}</p><div class="demo-options">${[['up','B tăng 8','B gains 8'],['down','B giảm 8','B loses 8'],['same','B không đổi','B unchanged']].map(([key,vi,en])=>`<button data-demo-choice="${key}" aria-pressed="${demoChoice===key}" class="${demoChoice===key?(key===(external?'same':'up')?'correct':'wrong'):''}">${t(vi,en)}</button>`).join('')}</div><div id="demo-feedback" class="demo-feedback" aria-live="polite">${demoChoice?demoFeedback():''}</div></div><p class="demo-caption">${t('Minh họa một quan hệ; không phải bài đo năng lực và không cộng vào tiến độ học.','One relationship only: this is not an assessment and does not count towards learning progress.')}</p></div>`;
 $('#demo-host').querySelectorAll('[data-demo-mode]').forEach(button=>button.onclick=()=>{demoMode=button.dataset.demoMode;demoChoice=null;demoExplained=false;log('intro_demo_change',{mode:demoMode,ui_version:UI_RELEASE});renderDemo();$('#demo-host').querySelector(`[data-demo-mode="${demoMode}"]`).focus({preventScroll:true});});
 $('#demo-host').querySelectorAll('[data-demo-choice]').forEach(button=>button.onclick=()=>{demoChoice=button.dataset.demoChoice;demoExplained=false;log('intro_demo_prediction',{mode:demoMode,choice:demoChoice,ui_version:UI_RELEASE});renderDemo();$('#demo-host').querySelector(`[data-demo-choice="${demoChoice}"]`).focus({preventScroll:true});});
 const explain=$('#demo-explain');if(explain)explain.onclick=()=>{demoExplained=true;log('intro_demo_explanation',{mode:demoMode,ui_version:UI_RELEASE});renderDemo();$('#demo-feedback').setAttribute('tabindex','-1');$('#demo-feedback').focus({preventScroll:true});};
}
function demoFeedback(){
 const ext=demoMode==='outside',correct=demoChoice===(ext?'same':'up');
 if(!demoExplained)return `${correct?t('Dự đoán của em phù hợp. Em hãy nói vì sao trước khi mở giải thích.','Your prediction fits. Try explaining why before opening the explanation.'):t('Hãy theo dõi riêng tủ B: có sách đi vào hay đi ra không? Em có thể chọn lại.','Track cupboard B: do any books enter or leave it? You can choose again.')}<br><button id="demo-explain">${t('Quan sát và đối chiếu','Observe and compare')}${icon('eye','small')}</button>`;
 return `${ext?t('A giảm 8, B không nhận thêm sách nên giữ nguyên. Điều kiện hai tủ bằng nhau được viết:','A loses 8 while B stays unchanged. Equal final counts are represented by:'):t('A giảm 8 và B tăng 8. Điều kiện hai tủ bằng nhau được viết:','A loses 8 and B gains 8. Equal final counts are represented by:')}<span class="equation" aria-label="${ext?t('x trừ tám bằng y','x minus eight equals y'):t('x trừ tám bằng y cộng tám','x minus eight equals y plus eight')}">x − 8 = ${ext?'y':'y + 8'}</span>${ext?t('Tổng số sách còn lại trong hai tủ giảm 8. Thay đổi câu chuyện làm thay đổi quan hệ.','The total remaining in the cupboards decreases by 8. A changed story requires a changed relationship.'):t('Tổng số sách trong hai tủ không đổi. Hãy thử đổi tình huống thành “Để ra ngoài”.','The combined total stays unchanged. Try the “Take outside” situation next.')}`;
}
function journeyNames(){return[t('Hiểu đề','Understand'),t('Chọn đại lượng','Quantities'),t('Lập quan hệ','Relationships'),t('Lập phương trình / hệ','Equation / system'),t('Giải','Solve'),t('Kiểm tra, giải thích','Check and interpret')];}
function renderJourney(){
 const descriptions=[
 ['Đề đang hỏi gì, ở thời điểm nào?','What is asked, and at which time?','Đọc câu chuyện, phân biệt điều đã biết với điều cần tìm.','Read the situation and separate known information from what must be found.'],
 ['Ẩn này đại diện cho điều gì?','What does the unknown represent?','Gắn tên, đơn vị và điều kiện phù hợp cho đại lượng em chọn.','State the meaning, unit and relevant conditions of the chosen quantity.'],
 ['Quan hệ này dựa vào câu nào?','Which sentence supports this relationship?','Theo dõi riêng từng đại lượng; nói lại sự thay đổi bằng lời của em.','Track each quantity separately and explain the change in your own words.'],
 ['Những quan hệ đã đủ mô tả tình huống chưa?','Do the relationships describe the situation?','Biểu diễn các mối liên hệ bằng phương trình hoặc hệ phương trình.','Represent the relationships as an equation or system of equations.'],
 ['Phép biến đổi và phép tính có đúng không?','Are the calculations and transformations valid?','Giải mô hình đã lập; chú ý điều kiện xác định khi có ẩn ở mẫu.','Solve your model, paying attention to domain restrictions when a variable appears in a denominator.'],
 ['Kết quả có hợp lý trong câu chuyện không?','Does the result make sense in the story?','Thay lại dữ kiện, kiểm tra đơn vị và điều kiện, rồi trả lời câu hỏi ban đầu.','Check the original facts, units and conditions, then answer the original question.']
 ];
 const item=descriptions[journeyIndex];$('#journey-detail').innerHTML=`<span class="icon-disc">${icon(['book','pencil','link','grid','settings','check'][journeyIndex])}</span><p><strong>${t(item[0],item[1])}</strong>${t(item[2],item[3])}</p>`;
 document.querySelectorAll('[data-journey]').forEach(x=>x.setAttribute('aria-pressed',String(+x.dataset.journey===journeyIndex)));
}
function renderSupport(){
 const items=[
 [1,'book','Có gợi ý từng bước','Hints from the start','Gợi ý hiện sẵn. Phù hợp khi em muốn có một điểm tựa để bắt đầu.','Hints stay visible when you need a starting point.'],
 [2,'pencil','Tự thử rồi mở gợi ý','Try first, then a hint','Em tự suy nghĩ và chọn lúc cần xem thêm một gợi ý.','Think first and choose when to open a hint.'],
 [3,'leaf','Tự làm trước khi xem trợ giúp','Start independently','Tự đọc, lập và kiểm tra; các công cụ hỗ trợ vẫn luôn có thể mở.','Read, model and check on your own. Support remains available.']
 ];
 $('#support-grid').innerHTML=items.map(([n,ic,vi,en,dv,de])=>`<button class="support-card" data-support="${n}" aria-pressed="${state.settings.support===n}"><span class="support-top"><span class="icon-disc">${icon(ic)}</span><span class="support-check" aria-hidden="true">${state.settings.support===n?'✓':''}</span></span><h3>${t(vi,en)}</h3><p>${t(dv,de)}</p></button>`).join('');
 document.querySelectorAll('[data-support]').forEach(btn=>btn.onclick=()=>{state.settings.support=+btn.dataset.support;save();renderSupport();$('#support-status').textContent=t('Đã chọn: ','Selected: ')+t(items[state.settings.support-1][2],items[state.settings.support-1][3]);$(`[data-support="${state.settings.support}"]`).focus({preventScroll:true});});
}
function lessonCard(l){
 const p=state.progress[l.id],cnt=p?Object.values(p.steps||{}).filter(s=>s.done).length:0;
 const shades={transfer:['#edf2e8','#285b48'],tickets:['#f3efe2','#796533'],growth:['#eaf1eb','#285b48'],motion:['#eaf0f3','#426f82'],fee:['#f4f0e5','#7c6735'],work:['#edf0e5','#586c37'],travel:['#eaf1f1','#376d70'],product:['#f0eeea','#655e4c']}[l.family];
 return `<article class="card lesson-card" style="--family-light:${shades[0]};--family-ink:${shades[1]}"><div class="lesson-card-top">${icon(familyIcons[l.family])}<span>${esc(b(DATA.families[l.family]))}</span></div><div class="lesson-card-body"><div class="lesson-card-meta"><span class="tag">${l.id}</span><span>${[t('Làm quen','Explore'),t('Luyện thêm','Practise'),t('Thử thách','Challenge')][l.level-1]}</span></div><h3>${esc(b(l.title))}</h3><p class="goal">${esc(b(l.goal))}</p><div class="lesson-kind">${esc(b(l.kind))}</div>${p?`<div class="progressline" role="img" aria-label="${cnt}/6 ${t('bước có câu trả lời đúng gần nhất','steps with a correct latest answer')}"><span style="width:${cnt/6*100}%"></span></div><p class="card-status">${cnt}/6 ${t('bước có câu trả lời đúng gần nhất','steps with a correct latest answer')} · ${t('Lượt','Attempt')} ${p.number||1}</p>`:''}</div><div class="lesson-card-foot"><button data-lesson="${l.id}">${p?t('Mở bài đã học','Open saved lesson'):t('Khám phá bài này','Explore this lesson')}${icon('arrow','small')}</button><small>~${l.minutes} ${t('phút dự kiến','min, estimated')}</small></div></article>`;
}
function bindLessonCards(){document.querySelectorAll('[data-lesson]').forEach(x=>x.onclick=()=>openLesson(x.dataset.lesson));}
function searchKey(text){return String(text).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');}
function library(){
 $('#main').innerHTML=`<div class="library-heading"><div><div class="eyebrow">${t('Kho học liệu · '+Object.keys(DATA.families).length+' nhóm quan hệ','Learning library · '+Object.keys(DATA.families).length+' relationship families')}</div><h1>${t('Bắt đầu từ điều<br>em muốn hiểu.','Begin with what<br>you want to understand.')}</h1><p>${t('Chọn một tình huống, thử một cách nghĩ. Mỗi bài có sáu bước, mô phỏng và một bài củng cố để em tự làm tiếp.','Choose a situation and try a way of thinking. Each lesson has six steps, a simulation and a consolidation task to work on next.')}</p></div><div class="side-fact" aria-hidden="true">${BANK.length}<small>${t('câu chuyện để khám phá','stories to explore')}</small></div></div><div class="filters"><label for="search">${t('Tìm bài','Find a lesson')}<input id="search" type="search" value="${esc(search)}" placeholder="${t('Tên bài, dữ kiện hoặc mã…','Title, fact or code…')}" autocomplete="off"></label><label for="family">${t('Nhóm quan hệ','Relationship family')}<select id="family"><option value="">${t('Tất cả nhóm','All families')}</option>${Object.entries(DATA.families).map(([k,v])=>`<option value="${k}" ${filter===k?'selected':''}>${esc(b(v))}</option>`).join('')}</select></label><label for="level">${t('Mức thử thách','Challenge level')}<select id="level"><option value="">${t('Mọi mức','All levels')}</option>${[1,2,3].map(i=>`<option value="${i}" ${level==i?'selected':''}>${[t('Làm quen','Explore'),t('Luyện thêm','Practise'),t('Thử thách','Challenge')][i-1]}</option>`).join('')}</select></label></div><div class="filter-chips" aria-label="${t('Chọn nhanh nhóm quan hệ','Quick family filters')}"><button data-family="" aria-pressed="${!filter}">${t('Tất cả','All')}</button>${Object.entries(familyShort).map(([key,lab])=>`<button data-family="${key}" aria-pressed="${filter===key}">${t(lab[0],lab[1])}</button>`).join('')}</div><div class="result-line"><span id="match-count" role="status"></span><button class="text-button" id="reset-filters">${t('Đặt lại bộ lọc','Reset filters')}</button></div><div id="library-results" class="grid lesson-cards"></div><p class="quiet" style="margin-top:1.4rem">${t('Số liệu trong các tình huống được xây dựng cho mục đích luyện tập. Thời lượng chỉ là ước tính, không phải giới hạn làm bài.','The situations use hypothetical learning data. Durations are estimates, not time limits.')}</p>`;
 $('#search').oninput=e=>{search=e.target.value;renderLibraryResults();};$('#family').onchange=e=>{filter=e.target.value;renderLibraryResults();};$('#level').onchange=e=>{level=e.target.value;renderLibraryResults();};
 document.querySelectorAll('[data-family]').forEach(btn=>btn.onclick=()=>{filter=btn.dataset.family;$('#family').value=filter;renderLibraryResults();});
 $('#reset-filters').onclick=resetLibraryFilters;renderLibraryResults();
}
function resetLibraryFilters(){filter='';search='';level='';$('#search').value='';$('#family').value='';$('#level').value='';renderLibraryResults();$('#search').focus({preventScroll:true});}
function renderLibraryResults(){
 const list=BANK.filter(l=>(!filter||l.family===filter)&&(!level||l.level===+level)&&(!search||searchKey(b(l.title)+' '+b(l.story)+' '+l.id).includes(searchKey(search))));
 $('#match-count').textContent=t(`${list.length} / ${BANK.length} bài phù hợp`,`${list.length} / ${BANK.length} matching lessons`);
 $('#library-results').innerHTML=list.length?list.map(lessonCard).join(''):`<div class="empty-results">${icon('book')}<h3>${t('Chưa tìm thấy tình huống phù hợp.','No matching situations yet.')}</h3><p class="small muted">${t('Thử một từ khóa ngắn hơn, mã bài hoặc bỏ bớt bộ lọc.','Try a shorter keyword, a lesson code or fewer filters.')}</p><button id="empty-reset">${t('Xem lại tất cả bài','Show all lessons')}</button></div>`;
 document.querySelectorAll('[data-family]').forEach(btn=>btn.setAttribute('aria-pressed',String(btn.dataset.family===filter)));bindLessonCards();if($('#empty-reset'))$('#empty-reset').onclick=resetLibraryFilters;
}
function lesson(){
 simController?.destroy();const p=progress();stage=Math.min(5,Math.max(0,stage));p.lastStage=stage;
 $('#main').innerHTML=`<div class="breadcrumb"><button id="back">${icon('back','small')}${t('Kho học liệu','Learning library')}</button><span aria-hidden="true">/</span><span>${esc(b(DATA.families[current.family]))}</span><span class="tag">${current.id}</span></div><div class="lesson-heading"><div><h1>${esc(b(current.title))}</h1><p>${esc(b(current.goal))}</p></div><span class="lesson-emblem">${icon(familyIcons[current.family])}</span></div><div class="attempt-bar"><span class="attempt-state"><span class="status-dot" aria-hidden="true"></span>${t('Lượt làm','Attempt')} ${p.number}${p.seenBefore?' · '+t('Luyện lại bài đã gặp','Previously seen lesson'):''}</span><div class="actions"><button id="lesson-support">${t('Mức trợ giúp','Support level')} ${state.settings.support}</button><button id="lesson-guide">${t('Hướng dẫn','Help')}</button><button id="attempt-history">${t('Lịch sử lượt làm','Attempt history')}</button><button id="restart-current">${t('Làm lại từ đầu','Start again')}</button></div></div>${p.legacy?`<p class="notice small">${t('Dữ liệu v5.0 được giữ lại. Dấu ○ ghi nhận bước đã từng trả lời đúng ở bản cũ; bản cũ chưa lưu đầy đủ câu trả lời gần nhất và bản nháp.','Your v5.0 records are preserved. A ○ marks a step answered correctly in the old version, which did not save complete latest answers and drafts.')}</p>`:''}<section class="panel story-panel"><div class="eyebrow">${t('Đề bài','Problem')}</div><p id="story">${esc(b(current.story))}</p><div class="actions"><button id="speak">▶ ${t('Nghe đề','Read aloud')}</button><button id="stop-speech">■ ${t('Dừng đọc','Stop reading')}</button><button id="lesson-print">${icon('print','small')}${t('In phiếu làm bài','Print worksheet')}</button><button id="glossary">${t('Giải nghĩa từ ngữ','Key words')}</button><a href="#task" class="button mobile-jump">${t('Đến câu hỏi ↓','Go to question ↓')}</a></div><p id="audio-status" class="small muted" aria-live="polite"></p><div id="reading-main"></div></section><div class="lesson-grid"><section class="panel scene-panel"><div id="sim"></div><details class="source-notes"><summary>${t('Mục tiêu và số liệu bài học','Learning goal and data')}</summary><p>${esc(b(current.goal))}</p><p class="small">${t('Số liệu trong bài được xây dựng để luyện tập. Giá trị đang thử trong mô phỏng chưa chắc là nghiệm.','Numbers are constructed for practice. A trial value in the simulation is not necessarily a solution.')}</p></details></section><div class="learning-column"><nav class="steps" aria-label="${t('Các bước giải','Solution steps')}">${stageNames().map((name,i)=>`<button data-stage="${i}" aria-current="${stage===i&&p.lastView!=='variant'?'step':'false'}"><span class="step-dot">${p.steps[i]?.done?(p.steps[i].legacyCompletion?'○':'✓'):i+1}</span>${name}</button>`).join('')}</nav><section class="panel" id="task" tabindex="-1"></section></div></div>`;
 $('#back').onclick=()=>go('library');$('#lesson-guide').onclick=helpDialog;$('#lesson-support').onclick=settings;$('#restart-current').onclick=()=>restartDialog();$('#attempt-history').onclick=()=>attemptHistory(current.id);
 document.querySelectorAll('[data-stage]').forEach(button=>button.onclick=()=>{stage=+button.dataset.stage;p.lastStage=stage;p.lastView='step';log('step_open',{lesson:current.id,step:current.steps[stage].id});touch();lesson();$('#task').focus({preventScroll:true});});
 $('#speak').onclick=readAloud;$('#stop-speech').onclick=()=>{readAloud.token=(readAloud.token||0)+1;window.speechSynthesis?.cancel();tts?.pause();$('#audio-status').textContent=t('Đã dừng đọc.','Reading stopped.');};$('#glossary').onclick=glossary;$('#lesson-print').onclick=()=>worksheetDialog(current);
 renderReading($('#reading-main'),'main');simulation();if(p.lastView==='variant')variant();else renderStep();touch();
}
function aboutPage(){
 $('#main').innerHTML=`<section class="about-hero"><div><div class="eyebrow">${t('Về dự án','About the project')}</div><h1>${t('Cây cầu từ hiểu<br>đến tự chủ.','A bridge from understanding<br>to independence.')}</h1><p>${t('Không phải một công cụ đưa người học thẳng đến đáp án. Đây là một không gian để thử, quan sát, giải thích và từng bước tự xây dựng lời giải.','Not a tool that carries the learner straight to an answer. A space to try, observe, explain and gradually build a solution of their own.')}</p><div class="actions"><button class="primary" data-go="library">${t('Trải nghiệm học liệu','Explore the lessons')}${icon('arrow','small')}</button><button data-go="teacher">${t('Dành cho giáo viên','For teachers')}</button></div></div><figure><img class="bridge-art" src="${esc(SITE.hero)}" alt="${t('Cây cầu kết nối Toán học với cuộc sống.','A bridge connecting mathematics and everyday life.')}" width="1000" height="529"><figcaption class="art-credit">${t('Minh họa AI từ bộ bìa nhật ký do nhóm cung cấp.','AI illustration from the supplied journal cover artwork.')}</figcaption></figure></section><section class="name-panel"><div class="eyebrow">${t('Tên đề tài nghiên cứu','Research-project title')}</div><p>${esc(DATA.title)}</p></section><div class="about-stats">${[[BANK.length,'bài học chính','main lessons'],[BANK.filter(x=>x.variant).length,'bài củng cố','consolidation tasks'],[6,'bước trong mỗi bài','steps per lesson'],[3,'mức hỗ trợ','support levels']].map(([n,vi,en])=>`<div class="about-stat"><strong>${n}</strong><span>${t(vi,en)}</span></div>`).join('')}</div>
 <section class="section"><div class="section-heading"><div><div class="eyebrow">${t('Ý nghĩa của tên gọi','The meaning of our name')}</div><h2>${t('Ba kết nối, một định hướng.','Three connections, one purpose.')}</h2></div></div><div class="grid">${[
 ['bridge','Cuộc sống ↔ Toán học','Everyday life ↔ Mathematics','Từ tình huống đến đại lượng, quan hệ, phương trình; rồi đưa kết quả trở lại giải thích tình huống.','Move from a situation to quantities, relationships and equations, then interpret the result in its original context.'],
 ['leaf','Hỗ trợ → Tự chủ','Support → Independence','Người học tự thử, chọn lúc mở gợi ý và tập giải thích. Trợ giúp là điểm tựa, không phải một lời giải để chép lại.','Learners try, choose when to open hints and explain their ideas. Support is a starting point, not an answer to copy.'],
 ['link','Bài đã học → Bài mới','Familiar task → New task','Câu chuyện có thể khác nhưng mối liên hệ có thể được sử dụng lại. Bài củng cố tạo cơ hội để tự thử tiếp.','Different stories may share mathematical relationships. Consolidation offers an opportunity to try the connection again.']
 ].map(([ic,vi,en,pv,pe])=>`<article class="about-card"><span class="icon-disc">${icon(ic)}</span><h3>${t(vi,en)}</h3><p>${t(pv,pe)}</p></article>`).join('')}</div></section>
 <section class="section"><div class="section-heading"><div><div class="eyebrow">${t('Thiết kế và kiểm chứng','Design and verification')}</div><h2>${t('Nói đúng điều sản phẩm làm được.','Describe what the product actually does.')}</h2></div></div><div class="two-columns"><article class="about-card"><span class="tag">${t('Có thể trải nghiệm trong bản này','Available in this version')}</span><h3>${t('Công cụ hỗ trợ quá trình học','Tools for the learning process')}</h3><div class="scope-list">${[
 ['Mô phỏng theo từng tình huống, có mô tả bằng chữ.','Situation-specific simulations with text descriptions.'],['Sáu bước, gợi ý theo yêu cầu, ví dụ nhỏ và lời giải tham khảo.','Six steps, optional hints, smaller examples and worked solutions.'],['Phiếu đọc hiểu, bài củng cố và lịch sử nhiều lượt làm.','Reading notes, consolidation and multi-attempt history.'],['Tiếng Việt / English; tùy chọn chữ lớn, tương phản và giảm chuyển động.','Vietnamese / English, large text, high contrast and reduced motion.'],['Xuất / nhập tiến độ; ghi trợ giúp đã sử dụng.','Progress export / import and records of support use.']
 ].map(([vi,en])=>`<div class="scope-item">${icon('check')}<span>${t(vi,en)}</span></div>`).join('')}</div></article><article class="about-card"><span class="evidence-state">${t('Chưa công bố kết quả thực nghiệm tại đây','No learning-effect results published here')}</span><h3>${t('Điều cần đối chiếu ngoài màn hình','What needs evidence beyond the screen')}</h3><p>${t('Dấu ✓ cho biết câu trả lời được kiểm tra gần nhất là đúng. Nó không chứng nhận năng lực mô hình hóa hay thay thế một bài làm độc lập.','A check mark means the latest checked answer is correct. It does not certify modelling competence or replace independent student work.')}</p><p>${t('Ở bài củng cố, hệ thống tự kiểm tra đáp số; cách đặt ẩn, phương trình và lập luận cần được người học hoặc giáo viên xem lại.','For consolidation, the app checks numerical answers. Variable definitions, equations and reasoning need learner or teacher review.')}</p><p>${t('Gói website này chưa đính kèm dữ liệu thực nghiệm giáo dục. Các con số ở trên mô tả cấu trúc học liệu, không phải mức tăng thành tích.','This website package does not include educational-experiment data. The counts above describe the learning materials, not achievement gains.')}</p></article></div><div class="privacy-panel"><h3>${t('AI là một kênh trợ giúp, không phải người xác nhận đáp án.','AI is a support channel, not an answer validator.')}</h3><p>${t('Người học chủ động tạo và sao chép yêu cầu, dùng công cụ AI bên ngoài rồi quay lại đối chiếu. Website không tự gửi câu hỏi và không khẳng định phản hồi AI luôn đúng. Phần học chính vẫn sử dụng được mà không cần AI.','Learners create and copy a request, use an external AI tool and return to check its response. This website does not automatically send questions or certify AI answers. Core lessons work without AI.')}</p></div></section>
 <section class="section"><div class="section-heading"><div><div class="eyebrow">${t('Con người và sự đồng hành','People behind the project')}</div><h2>${t('Một hành trình học và nghiên cứu.','A journey of learning and inquiry.')}</h2></div></div><div class="people-row"><div class="person"><small>${t('Học sinh thực hiện','Student researcher')}</small><strong>Phan Hoàng An Nhiên</strong><p>${t('Dự án “Cầu nối Toán học”','Math Bridge project')}</p></div><div class="person"><small>${t('Giáo viên hướng dẫn','Teacher mentor')}</small><strong>Nguyễn Việt Hoàng</strong><p>${t('Đồng hành và phản biện chuyên môn','Mentoring and subject-matter review')}</p></div><div class="person"><small>${t('Đơn vị','School')}</small><strong>THCS Nguyễn An Khương</strong><p>${t('Năm học 2026–2027','School year 2026–2027')}</p></div></div><div class="credits-note"><p>${t('Mã giao diện của bản nâng cấp này được tạo và chỉnh sửa với hỗ trợ AI. Minh họa lấy từ bộ bìa AI do nhóm cung cấp. Phạm vi hỗ trợ được ghi riêng, không đồng nhất với phần nghiên cứu độc lập của học sinh.','This interface upgrade was created and edited with AI assistance. Artwork comes from the supplied AI-generated covers. These contributions are documented separately from the student’s independent research.')}</p><button id="about-credits" class="text-button">${t('Xem nguồn và phạm vi đóng góp','View sources and contribution scope')}${icon('arrow','small')}</button></div></section>`;
 bindRoutes($('#main'));$('#about-credits').onclick=creditsDialog;
}
function teacherLinks(){go('teacher');}
function teacherPage(){
 $('#main').innerHTML=`<div class="page-intro"><div class="eyebrow">${t('Dành cho giáo viên','For teachers')}</div><h1>${t('Một tình huống.<br>Nhiều cơ hội để học sinh giải thích.','One situation.<br>More room for student reasoning.')}</h1><p class="muted">${t('Mở thẳng bài học, in phiếu làm bài và xem đúng ý nghĩa của dữ liệu luyện tập. Đây không phải bảng điểm lớp hay hệ thống thu dữ liệu tự động.','Launch a lesson directly, print a worksheet and interpret practice records carefully. This is not a class gradebook or an automatic data-collection service.')}</p></div><div class="two-columns"><section class="teacher-launch"><h2>${t('Chọn tình huống cho tiết học','Choose a classroom situation')}</h2><label for="teacher-lesson">${t('Bài học trong ngân hàng hiện có','Lesson from the existing bank')}</label><select id="teacher-lesson">${BANK.map(l=>`<option value="${l.id}">${l.id} · ${esc(b(l.title))}</option>`).join('')}</select><div class="teacher-preview" id="teacher-preview"></div><div class="actions"><button class="primary" id="teacher-open">${t('Mở thẳng bài học','Open lesson')}${icon('arrow','small')}</button><button id="teacher-copy">${icon('link','small')}${t('Sao chép liên kết','Copy link')}</button><button id="teacher-print">${icon('print','small')}${t('In phiếu làm bài','Print worksheet')}</button></div><p class="copy-status" id="teacher-status" role="status"></p><p class="teacher-nudge">${t('Liên kết bài học đi thẳng vào nhiệm vụ, không qua demo trang chủ. Bản tệp ngoại tuyến cần được gửi kèm cho người nhận; đường dẫn trên máy của thầy không mở được ở máy khác.','Lesson links bypass the homepage demo. An offline file must be shared with the recipient; a local file path on your computer is not a public link.')}</p></section><section class="about-card"><div class="eyebrow">${t('Giữ vai trò chủ động cho người học','Keep the learner in control')}</div><h3>${t('Quan sát cách nghĩ, không chỉ đáp số.','Observe the thinking, not only the answer.')}</h3><ol class="guide-points"><li>${t('Mời học sinh tự đọc và nói lại dữ kiện trước khi mở trợ giúp.','Ask students to read and restate the facts before opening support.')}</li><li>${t('Sau khi thao tác mô phỏng, hỏi: “Điều gì thay đổi? Quan hệ này dựa vào câu nào?”.','After using the simulation, ask what changed and which sentence supports the relationship.')}</li><li>${t('Đối chiếu ghi chú, phương trình và giải thích trên giấy hoặc trong phiếu đọc hiểu.','Review notes, equations and explanations on paper or in the reading worksheet.')}</li><li>${t('Bài đo độc lập cần được tách khỏi bài luyện đã có gợi ý hoặc đáp án. Phiếu in ở đây là học liệu, chưa phải công cụ đánh giá đã kiểm định.','Independent assessment should be separate from supported practice. The printable worksheet is learning material, not a validated assessment instrument.')}</li></ol><button class="text-button" id="teacher-guide">${t('Mở hướng dẫn đầy đủ','Open the full guide')}${icon('arrow','small')}</button></section></div><section class="section"><div class="section-heading"><div><div class="eyebrow">${t('Công cụ của đợt triển khai','Deployment resources')}</div><h2>${t('Kết nối đúng tài liệu, đúng đợt.','Use the right resources for your study.')}</h2><p class="small muted">${t('Chỉ những đường dẫn đã được cấu hình mới có thể mở. Bộ câu hỏi khảo sát, đề đo A/B và máy chủ nhận dữ liệu không được tự tạo lại trong lần đổi giao diện này.','Only configured links can be opened. Surveys, independent A/B instruments and data-receiver services are not recreated in this interface upgrade.')}</p></div></div><div class="two-columns"><article class="about-card"><h3>${t('Tài liệu và công cụ riêng','Separate tools and materials')}</h3><div id="resource-list" class="resource-list"></div><p class="quiet">${t('Người quản trị có thể gắn đường dẫn đã kiểm tra trong assets/config.js; không đặt dữ liệu cá nhân hoặc khóa bí mật vào tệp cấu hình công khai.','The site maintainer can add verified links in assets/config.js. Do not put personal data or secrets in this public configuration file.')}</p></article><article class="about-card"><h3>${t('Tiến độ và dữ liệu trên thiết bị này','Records on this device')}</h3><p>${t('Xuất tiến độ để sao lưu bài làm. Chỉ bật ghi sự kiện nghiên cứu khi đã thông tin và có sự đồng ý phù hợp. Đổi mã nghiên cứu không phải là đổi người học.','Export progress to back up work. Enable research-event recording only after information and appropriate consent. Changing a research code does not switch learners.')}</p><div class="actions"><button data-go="progress">${t('Xem và xuất tiến độ','View and export progress')}</button><button id="research-link">${t('Tham gia nghiên cứu','Research participation')}</button></div><p class="quiet">${t('Bản HTML / website tĩnh chưa tự gửi dữ liệu lên máy chủ. Công cụ nhận của đợt cần được kiểm thử riêng.','The HTML / static site does not automatically submit data to a server. A study receiver needs separate testing.')}</p></article></div></section><div class="privacy-panel"><h3>${t('Trước khi dùng ở lớp','Before classroom use')}</h3><p>${t('Thử trên thiết bị thực tế: mở bài, đổi giá trị mô phỏng, gõ đáp án, lưu rồi tải lại. Kiểm tra thêm bàn phím, giọng đọc, mạng và việc xuất / nhập. Kiểm thử giao diện không thay cho kiểm chứng hiệu quả học tập.','Test on actual devices: open a lesson, change a simulation value, type an answer, save and reload. Check keyboard operation, speech, connectivity and export / import. Interface tests do not establish learning effectiveness.')}</p><div class="actions"><button id="teacher-settings">${icon('settings','small')}${t('Tùy chỉnh tiếp cận','Accessibility settings')}</button><button id="teacher-credits">${t('Mã nguồn và đóng góp AI','Code and AI contributions')}</button></div></div>`;
 const chooser=$('#teacher-lesson');chooser.value=current?.id||state.lastLesson||BANK[0].id;
 const getLesson=()=>BANK.find(l=>l.id===chooser.value);
 const draw=()=>{const l=getLesson();$('#teacher-preview').innerHTML=`<strong>${esc(b(l.title))}</strong><p>${esc(b(l.goal))}</p><small>${esc(b(l.kind))} · ~${l.minutes} ${t('phút dự kiến','min, estimated')}</small>`;$('#teacher-status').textContent='';};chooser.onchange=draw;draw();
 $('#teacher-open').onclick=()=>openLesson(chooser.value);$('#teacher-copy').onclick=async()=>{const base=location.href.split('#')[0];await copyText(base+'#/lesson/'+chooser.value,$('#teacher-status'));};$('#teacher-print').onclick=()=>worksheetDialog(getLesson());
 $('#teacher-guide').onclick=helpDialog;$('#research-link').onclick=research;$('#teacher-settings').onclick=settings;$('#teacher-credits').onclick=creditsDialog;bindRoutes($('#main'));renderResources();
}
function renderResources(){
 const config=SITE.resources||{};const service=window.CAU_NOI_SERVICE_URL;
 $('#resource-list').innerHTML=[['survey','Khảo sát học sinh','Student survey'],['assessment','Bài đo độc lập A/B','Independent A/B instrument'],['dashboard','Bảng tổng hợp giáo viên','Teacher data dashboard'],['receiver','Nơi nhận gói dữ liệu','Data-package receiver']].map(([key,vi,en])=>{
  let raw=config[key]||(service&&key!=='dashboard'?service+(service.includes('?')?'&':'?')+'page='+({survey:'survey',assessment:'assessment',receiver:'receive'}[key]):'');
  let safe='';try{if(raw){const u=new URL(raw,location.href);if(['https:','http:'].includes(u.protocol)||u.protocol==='file:'&&location.protocol==='file:')safe=u.href;}}catch(_){}
  return `<div class="resource"><span>${t(vi,en)}</span>${safe?`<a href="${esc(safe)}" target="_blank" rel="noopener noreferrer">${t('Mở tài liệu','Open resource')} ↗</a>`:`<small>${t('Chưa gắn liên kết','Not configured')}</small>`}</div>`;
 }).join('');
}
async function copyText(text,host){
 let copied=false;try{await navigator.clipboard.writeText(text);copied=true;}catch(_){const area=document.createElement('textarea');area.value=text;area.style.cssText='position:fixed;left:-9999px;top:0';document.body.append(area);area.select();try{copied=document.execCommand('copy');}catch(_){}area.remove();}
 if(host)host.textContent=copied?t('Đã sao chép liên kết bài học.','Lesson link copied.'):t('Chưa sao chép tự động được. Mở bài rồi sao chép địa chỉ trên trình duyệt.','Automatic copy is unavailable. Open the lesson and copy the browser address.');
}
function worksheetHTML(l){return `<div class="worksheet-preview"><div class="worksheet-brand">${t('Cầu nối Toán học · Phiếu làm bài','Math Bridge · Learning worksheet')}</div><h2>${esc(l.id+' · '+b(l.title))}</h2><div class="worksheet-meta"><span>${t('Họ tên / Mã:','Name / Code:')} ________________________</span><span>${t('Lớp:','Class:')} ________</span><span>${t('Ngày:','Date:')} ____________</span></div><p>${esc(b(l.story))}</p><h3>${t('1. Đề cho biết gì? Cần tìm gì?','1. What is given? What must be found?')}</h3><div class="writing-lines"></div><h3>${t('2. Chọn đại lượng, đơn vị và điều kiện.','2. Choose quantities, units and conditions.')}</h3><div class="writing-lines"></div><h3>${t('3. Giải thích mối liên hệ và lập phương trình / hệ phương trình.','3. Explain the relationships and build an equation / system.')}</h3><div class="writing-lines tall"></div><h3>${t('4. Giải và kiểm tra kết quả trong tình huống.','4. Solve and check the result in context.')}</h3><div class="writing-lines tall"></div><h3>${t('5. Em đã dùng hỗ trợ nào? Điều gì em muốn xem lại?','5. What support did you use? What would you revisit?')}</h3><div class="writing-lines"></div><p style="font-size:.68rem">${t('Phiếu luyện tập từ ngân hàng 5.1. Không có đáp án in sẵn. Không phải công cụ đo đã được kiểm định.','Practice sheet from bank 5.1, without printed answers. Not a validated assessment instrument.')}</p></div>`;}
function worksheetDialog(l){modal(`<h2>${t('Xem trước phiếu làm bài','Worksheet preview')}</h2><p class="small muted">${t('Phiếu dùng đúng đề trong ngân hàng, không kèm gợi ý hay đáp án. Chọn In để in giấy hoặc lưu theo tùy chọn của trình duyệt.','This sheet uses the exact bank problem without hints or answers. Choose Print to use the browser’s print options.')}</p><button class="primary" id="print-sheet-now">${icon('print','small')}${t('In phiếu này','Print this worksheet')}</button><hr class="separator">${worksheetHTML(l)}`);$('#print-sheet-now').onclick=()=>{let host=$('#worksheet-print');if(!host){host=el('section',{id:'worksheet-print'});document.body.append(host);}host.innerHTML=worksheetHTML(l);document.body.classList.add('print-worksheet');window.print();document.body.classList.remove('print-worksheet');};}
function creditsDialog(){modal(`<h2>${t('Nguồn và phạm vi đóng góp','Sources and contribution scope')}</h2><h3>${t('Học liệu và chức năng kế thừa','Preserved learning content and engine')}</h3><p>${t('Bản nâng cấp dựa trên tệp Cau_noi_Toan_hoc_v5_1_1(1).html do thầy cung cấp. Ngân hàng 48 bài chính, 48 bài củng cố, đáp án, mô hình mô phỏng và cấu trúc lưu tiến độ 5.1 được giữ lại.','This upgrade is based on the supplied Cau_noi_Toan_hoc_v5_1_1(1).html file. Its 48 main lessons, 48 consolidation tasks, answers, simulation models and 5.1 progress schema are preserved.')}</p><h3>${t('Mã giao diện có hỗ trợ AI','AI-assisted interface code')}</h3><p>${t('HTML, CSS và phần JavaScript giao diện mới của phiên bản 6.0 được tạo / chỉnh sửa với hỗ trợ AI trong phiên thiết kế này: điều hướng, trang chủ, demo giới thiệu, kho bài, bố cục bài học, trang dự án và trang giáo viên. Đây không phải tuyên bố học sinh tự viết toàn bộ mã.','Version 6.0 HTML, CSS and new interface JavaScript were created / edited with AI assistance in this design session: navigation, homepage, introductory demo, library, lesson layout, about and teacher pages. This is not a claim that the student independently wrote all code.')}</p><h3>${t('Minh họa','Artwork')}</h3><p>${t('Hình cây cầu được trích từ mẫu bìa “Ảnh Codex 18_17_01 21 thg 9, 2026-2.png” do nhóm cung cấp, là minh họa AI. Chữ tương tác và nội dung học vẫn là văn bản HTML. Các biểu tượng giao diện là SVG được tạo với hỗ trợ AI.','The bridge image is cropped from the supplied AI-generated cover “Ảnh Codex 18_17_01 21 thg 9, 2026-2.png”. Interactive labels and learning content remain HTML text. Interface SVG icons were created with AI assistance.')}</p><h3>${t('Cách đối chiếu','How to review')}</h3><p>${t('Trong gói mã nguồn, xem docs/THAY_DOI_6_1.md, docs/NGUON_VA_AI.md và docs/KIEM_THU_6_1.md. Nhóm cần tự đọc, kiểm tra và lưu nhật ký phần đã sử dụng, chỉnh sửa. Kiểm thử kỹ thuật không phải kết quả thực nghiệm sư phạm.','In the source package, see docs/THAY_DOI_6_1.md, docs/NGUON_VA_AI.md and docs/KIEM_THU_6_1.md. The team should read, verify and record what was used or changed. Technical QA is not a pedagogical experiment.')}</p>`);}
function bindShell(){
 $('#home').onclick=()=>go('home');$('#nav-home').onclick=()=>go('home');$('#nav-library').onclick=()=>go('library');$('#nav-progress').onclick=()=>go('progress');$('#nav-about').onclick=()=>go('about');
 $('#nav-help').onclick=helpDialog;$('#mobile-help').onclick=()=>{closeMenu();helpDialog();};$('#nav-settings').onclick=settings;$('#mobile-settings').onclick=()=>{closeMenu();settings();};
 $('#menu-toggle').onclick=()=>{const open=$('.site-header').classList.toggle('menu-open');$('#menu-toggle').setAttribute('aria-expanded',String(open));};
 $('#lang-toggle').onclick=()=>{state.settings.lang=L()==='vi'?'en':'vi';save();go(route);};
 window.addEventListener('popstate',()=>{if(location.hash&&!location.hash.startsWith('#/'))return;if($('#dialog').open)$('#dialog').close();readRoute();});
 document.addEventListener('click',event=>{const link=event.target.closest?.('a[href="#task"],a[href="#main"]');if(!link)return;const target=document.querySelector(link.getAttribute('href'));if(!target)return;event.preventDefault();target.scrollIntoView({behavior:'instant',block:'start'});target.focus({preventScroll:true});});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.site-header').classList.contains('menu-open')){closeMenu();$('#menu-toggle').focus();}});
 window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;if($('#install-app'))$('#install-app').hidden=false;});
 window.addEventListener('afterprint',()=>document.body.classList.remove('print-worksheet'));
 if(!SITE.portable&&'serviceWorker' in navigator&&/^https?:$/.test(location.protocol))navigator.serviceWorker.register('sw.js').catch(()=>{});
}
function closeMenu(){$('.site-header').classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');}

loadState();
$('#nav-help').onclick=helpDialog;
$('#close-dialog').onclick=()=>{window.speechSynthesis?.cancel();$('#dialog').close();};
$('#dialog').addEventListener('close',()=>{const target=modal.previousFocus?.isConnected?modal.previousFocus:$('#task')||$('#main');target?.focus({preventScroll:true});});
bindShell();
readRoute();
